# Compute Manhattan-to-boundary depth for each connected component (4-neighbor); compare sample lower-left demo4 component.
# Rebuild boolean labels from `gd` currently in persistent Python.
def comp_depth(cells,shape=(30,30)):
    S=set(cells); d={}; q=collections.deque()
    R,C=shape
    for r,c in cells:
        if any(not(0<=r+dr<R and 0<=c+dc<C) or (r+dr,c+dc) not in S for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]):
            d[(r,c)]=0;q.append((r,c))
    while q:
        p=q.popleft()
        for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            n=(p[0]+dr,p[1]+dc)
            if n in S and n not in d:
                d[n]=d[p]+1;q.append(n)
    return d
