# Validate a generic rule on the exact demo4 pair: components separated by divider color 1, fill each component by cyclic rings using diagonal corner marker sequence and boundary-layer depth.
def gen_by_components(arr, divider, background, orientation='TR', depthmode='bbox'):
    R,C=arr.shape; seen=set(); result=arr.copy(); comps0=[]
    for r in range(R):
      for c in range(C):
       if arr[r,c]==divider or (r,c) in seen: continue
       q=[(r,c)]; seen.add((r,c)); cells=[]
       for x,y in q:
        cells.append((x,y))
        for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
         a,b=x+dx,y+dy
         if 0<=a<R and 0<=b<C and arr[a,b]!=divider and (a,b) not in seen:
          seen.add((a,b));q.append((a,b))
       rs=[x for x,y in cells];cs=[y for x,y in cells];r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
       # try TR markers; collect initial background corner if followed by special, then stop at first later base.
       diag=[]
       for t in range(min(r1-r0+1,c1-c0+1)):
        v=int(arr[r0+t,c1-t])
        if v==background:
         if t==0: diag.append(v);continue
         break
        diag.append(v)
       if not any(v!=background for v in diag):
        continue
       dmap=comp_depth(cells,(R,C))
       for x,y in cells:
        if depthmode=='bbox': d=min(x-r0,r1-x,y-c0,c1-y)
        else: d=dmap[(x,y)]
        result[x,y]=diag[d%len(diag)]
       comps0.append((len(cells),(r0,r1,c0,c1),diag))
    return result,comps0
